      "full_text" : "《洛杉矶进口》这两周我一直在和印度工厂联系，我想用自己第一次经历来向大家证明，华人离开中国工厂是可以活下去的。我也需会被骗，被偷工减料，被损失，但总要去尝试。最坏结果就算我替其它华人进口商付学费学习经验了。请大家支持我！",
