      "full_text" : "德先生揭露 #茹露逼\n用小号\n在小严空间狂加男网友\n包括 德先生 本人\n#黄推假币辱割杀猪盘\n骚扰男网友\n 如歌茹露逼 \n你有多缺男人\n要去别人空间加男人呀\n你实在太low一点女性魅力没有\n到处骗粉蹭流量也红不了\n你如歌茹露逼就是个边角料被人唾弃\n还意淫自己是天花板\n你脑子进水了 https://t.co/bF8wH5O1zX",
