      "created_at" : "Fri Mar 28 23:24:20 +0000 2025",
      "favorited" : false,
      "full_text" : "@hannahandyogi @miraa976 @Hannahandyoga #茹露逼 就是个口含腌几把老娘们公鸭嗓弱反馈龅牙侏儒卷卷毛\n🥩贵老表子\n\n空间绿茶牌坊立\n脆皮乳鸽数第一\n出身低贱肉还贵\n露脸露臀还露逼\n可惜年老色又衰\n丑颜丑肤叹无力\n肌如坑洼粪坑泥\n肤若风干橘子皮\n\n皮燥肉厚褶子多\n手臂纹身黑道鸡\n假声假唱假名牌\n真老真丑真龌龊\n没钱没闲没伴侣\n无德无品有寂寞",
      "lang" : "zh",
