      "full_text" : "#茹露逼 #黄推假币辱割杀猪盘 \n😂有多羡慕嫉妒恨女网友们呀\n 长达近四年对所有开麦女网友\n人身攻击、P图丑化女网友\n脊柱弯曲弱反馈脑残茹露逼\n自称天花板肉贵却卖肉卖不出去\n狂言露脸露逼三字经不离口\n一桶中推😂😂\n茹露逼时间线上全是\n变态反社会人格就是\n杀猪盘的骗子\n中推臭大街茹地板😂 https://t.co/TrISvJy5n0",
