      "full_text" : "大卫消费自己也就算了，是他自己的事情，大家管不着，但他把消费网友说得如此振振有词，把造谣谩骂攻击网友空间说成追求事实真相空间，你大卫坏事做多了，一个腰子被割掉还不消停，另一个腰子也要被割才罢休 https://t.co/OUMJ0YrKrY",
