      "created_at" : "Tue Mar 18 00:48:10 +0000 2025",
      "favorited" : false,
      "full_text" : "#茹露逼 #黄推假币辱割杀猪盘 \n隶属 郭文贵诈骗团伙\n郭文贵近期发迷因币\n#茹露逼 同伙故意冒充墙内网友\n声称已投资郭币\n涨了七倍\n在各个群游说诈骗网友购买郭币\n此团伙多名成员曾组织唱歌群拉人\n网友务必远离郭文贵茹露逼杀猪盘团伙\n\n露脸露逼一桶中推的 \n#茹露逼 #黄推假币辱割杀猪盘 https://t.co/YYu0P7wUAp",
